/* tb-ai-palette */ .qc-shell { --canvas: var(--tb-ai-canvas, #F7F8FA); --surface: var(--tb-ai-surface, #FFFFFF); --text: var(--tb-ai-text, rgba(0,0,0,0.87)); --text-secondary: var(--tb-ai-text-secondary, rgba(0,0,0,0.54)); --border: var(--tb-ai-border, rgba(0,0,0,0.12)); --primary: var(--tb-ai-primary, var(--tb-primary-500, #00695C)); --on-primary: var(--tb-ai-on-primary, var(--tb-primary-contrast-500, #FFFFFF)); --accent: var(--tb-ai-accent, var(--tb-accent-500, #FF5722)); }
tb-icon {
  width: 1em;
  height: 1em;
  min-width: 1em;
  min-height: 1em;
  font-size: 24px;
  line-height: 1;
}

.qc-shell {
  --tb-ai-font: 'Inter',-apple-system,BlinkMacSystemFont,sans-serif;
  font-family: var(--tb-ai-font);
  --tb-ai-card-border: 1px solid rgba(226,232,240,0.8);
  --tb-ai-card-radius: 16px;
  --tb-ai-card-shadow: 0 2px 8px rgba(0,0,0,0.04);
  --tb-ai-card-padding: 16px;
  --tb-ai-card-title-size: 14px;
  --tb-ai-card-title-weight: 600;
  --tb-ai-card-title-color: var(--text);
  --tb-ai-card-title-line-height: 20px;
  --tb-ai-table-header-size: 12px;
  --tb-ai-table-header-weight: 600;
  --tb-ai-table-header-color: var(--text-secondary);
  --tb-ai-table-cell-size: 13px;
  --tb-ai-table-cell-weight: 400;
  --tb-ai-table-cell-color: var(--text);
  --tb-ai-table-divider-color: var(--border);
  height: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding: 20px;
  background: var(--canvas,#F8FAFC);
  color: var(--text,#1E293B);
  overflow-y: auto;
}

.qc-header {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 4px;
}

.qc-header__info {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.qc-header__title-row {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.qc-header__title {
  font-size: 22px;
  font-weight: 700;
  margin: 0;
  color: var(--text,#0F172A);
  letter-spacing: -0.02em;
}

.qc-header__subtitle {
  font-size: 13px;
  color: var(--text-secondary,#64748B);
}

.qc-header__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  font-size: 12px;
  color: var(--text-secondary,#64748B);
  margin-top: 4px;
}

.qc-header__meta-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.qc-header__meta-item tb-icon {
  font-size: 16px;
}

.qc-header__status-summary {
  font-weight: 500;
  color: #10B981;
}

.qc-header__status-summary.is-warn {
  color: #F59E0B;
}

.qc-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600; white-space: nowrap; flex: none;
}

.qc-badge__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%; white-space: nowrap; flex: none;
}

.qc-badge--online {
  background: rgba(16,185,129,0.12);
  color: #059669;
}

.qc-badge--online .qc-badge__dot {
  background: #10B981;
  box-shadow: 0 0 6px #10B981;
}

.qc-badge--offline {
  background: rgba(100,116,139,0.12);
  color: #64748B;
}

.qc-badge--offline .qc-badge__dot {
  background: #94A3B8;
}

.qc-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  border: 1px solid transparent;
  transition: all .15s ease;
}

.qc-btn tb-icon {
  font-size: 18px;
}

.qc-btn--ghost {
  background: var(--surface,#FFF);
  border: 1px solid var(--border,#E2E8F0);
  color: var(--text,#334155);
}

.qc-btn--ghost:hover {
  background: rgba(0,0,0,0.03);
}

.qc-btn--primary {
  background: var(--primary,#0284C7);
  color: var(--on-primary,#FFF);
}

.qc-btn--primary:hover {
  opacity: .92;
}

.qc-btn--sm {
  padding: 6px 12px;
  font-size: 12px;
}

.qc-btn:disabled {
  opacity: .5;
  cursor: not-allowed;
}

.qc-card {
  background: var(--surface,#FFF);
  border: var(--tb-ai-card-border);
  border-radius: var(--tb-ai-card-radius);
  box-shadow: var(--tb-ai-card-shadow);
  padding: var(--tb-ai-card-padding);
  box-sizing: border-box;
}

.qc-settings {
  display: flex;
  flex-direction: column;
  gap: 14px;
  background: #F1F5F9;
  border: 1px solid #CBD5E1;
}

.qc-settings__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.qc-settings__title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 700;
  color: #0F172A;
}

.qc-settings__desc {
  font-size: 12px;
  color: #64748B;
  margin-top: 2px;
}

.qc-settings__actions {
  display: flex;
  gap: 8px;
}

.qc-settings__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit,minmax(220px,1fr));
  gap: 10px;
}

.qc-setting-item {
  background: #FFF;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid #E2E8F0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.qc-setting-item__head {
  display: flex;
  align-items: center;
  gap: 6px;
}

.qc-setting-item__color-tag {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  background: var(--param-color,#0284C7);
}

.qc-setting-item__name {
  font-size: 12px;
  font-weight: 600;
  color: #1E293B;
}

.qc-setting-item__unit {
  font-size: 11px;
  color: #64748B;
  margin-left: auto;
}

.qc-setting-item__inputs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.qc-input-group {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.qc-input-group__label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  color: #64748B;
}

.qc-input {
  width: 100%;
  box-sizing: border-box;
  padding: 5px 8px;
  border: 1px solid #CBD5E1;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 600;
  background: #F8FAFC;
  color: #0F172A;
}

.qc-settings__msg {
  font-size: 12px;
  font-weight: 500;
  color: #059669;
}

.qc-settings__msg.is-error {
  color: #DC2626;
}

.qc-grid-params {
  display: grid;
  grid-template-columns: repeat(auto-fit,minmax(260px,1fr));
  gap: 16px;
}

.qc-param-card {
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: var(--surface,#FFF);
  border-top: 4px solid var(--param-color,#0284C7);
  transition: transform .2s ease,box-shadow .2s ease;
}

.qc-param-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(0,0,0,0.06);
}

.qc-param-card__top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px; flex-wrap: wrap;
}

.qc-param-card__title {
  font-size: 14px;
  font-weight: 700;
  color: var(--text,#1E293B);
}

.qc-param-card__limits-txt {
  display: block;
  font-size: 11px;
  color: var(--text-secondary,#64748B);
  margin-top: 2px;
}

.qc-param-card__status-tag {
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

.qc-param-card__status-tag--ok {
  background: rgba(16,185,129,0.12);
  color: #059669;
}

.qc-param-card__status-tag--warn {
  background: rgba(245,158,11,0.15);
  color: #D97706;
}

.qc-param-card__status-tag--crit {
  background: rgba(239,68,68,0.15);
  color: #DC2626;
}

.qc-param-card__status-tag--none {
  background: rgba(148,163,184,0.15);
  color: #64748B;
}

.qc-param-card__body {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.qc-param-card__main-val {
  display: flex;
  align-items: baseline;
  gap: 4px;
}

.qc-param-card__number {
  font-size: 32px;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--text,#0F172A);
  font-variant-numeric: tabular-nums;
}

.qc-param-card__unit {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-secondary,#64748B);
}

.qc-donut {
  position: relative;
  width: 64px;
  height: 64px;
  flex: none;
}

.qc-donut__svg {
  width: 100%;
  height: 100%;
  display: block;
}

.qc-donut__track {
  fill: none;
  stroke: #E2E8F0;
  stroke-width: 8;
}

.qc-donut__fill {
  fill: none;
  stroke: var(--param-color,#0284C7);
  stroke-width: 8;
  stroke-linecap: round;
  transition: stroke-dasharray .5s ease;
}

.qc-donut--warn .qc-donut__fill {
  stroke: #F59E0B;
}

.qc-donut--crit .qc-donut__fill {
  stroke: #EF4444;
}

.qc-donut__zone-text {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-secondary,#475569);
}

.qc-param-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(226,232,240,0.6);
}

.qc-param-card__trend {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary,#64748B);
}

.qc-param-card__trend tb-icon {
  font-size: 14px;
}

.qc-param-card__trend.is-up {
  color: #059669;
}

.qc-param-card__trend.is-down {
  color: #D97706;
}

.qc-sparkline-wrap {
  width: 90px;
  height: 24px;
}

.qc-sparkline {
  width: 100%;
  height: 100%;
  display: block;
}

.qc-sparkline__line {
  fill: none;
  stroke: var(--param-color,#0284C7);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.qc-flow-section {
  display: grid;
  grid-template-columns: 320px 1fr;
  gap: 20px;
  border-left: 5px solid #06B6D4;
  padding: 20px;
  align-items: stretch;
}

.qc-flow-section__overview {
  display: flex;
  flex-direction: column;
  gap: 14px;
  justify-content: space-between;
}

.qc-flow-section__title-row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.qc-flow-section__icon {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  background: #CFFAFE;
  color: #0891B2;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  flex: none;
}

.qc-flow-section__title {
  font-size: 16px;
  font-weight: 700;
  margin: 0;
  color: #0F172A;
}

.qc-flow-section__sub {
  font-size: 12px;
  color: #64748B;
  margin: 2px 0 0;
}

.qc-flow-section__kpi {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.qc-flow-section__val-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.qc-flow-section__value {
  font-size: 36px;
  font-weight: 800;
  color: #0F172A;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
}

.qc-flow-section__unit {
  font-size: 14px;
  font-weight: 600;
  color: #64748B;
}

.qc-flow-section__trend {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  font-weight: 600;
  color: #64748B;
}

.qc-flow-section__trend tb-icon {
  font-size: 16px;
}

.qc-flow-section__trend.is-up {
  color: #059669;
}

.qc-flow-section__trend.is-down {
  color: #0284C7;
}

.qc-flow-section__spark-box {
  background: #F8FAFC;
  border: 1px solid #E2E8F0;
  border-radius: 10px;
  padding: 10px;
}

.qc-flow-section__spark-title {
  font-size: 11px;
  font-weight: 600;
  color: #64748B;
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.qc-sparkline--flow .qc-sparkline__line {
  stroke: #06B6D4;
  stroke-width: 2.2;
}

.qc-flow-section__embed {
  min-height: 360px;
  height: 100%;
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid #E2E8F0;
}

.qc-flow-section__embed tb-dashboard-state {
  display: block;
  width: 100%;
  height: 100%;
}

.qc-views-wrapper {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.qc-tabs {
  display: flex;
  gap: 8px;
  border-bottom: 1px solid var(--border,#E2E8F0);
  padding-bottom: 2px;
  overflow-x: auto; flex-shrink: 0; max-width: 100%; min-width: 0; overflow-y: hidden;
}

.qc-tab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border-radius: 10px 10px 0 0;
  border: none;
  background: transparent;
  color: var(--text-secondary,#64748B);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all .15s ease;
  border-bottom: 2px solid transparent;
}

.qc-tab tb-icon {
  font-size: 18px;
}

.qc-tab.is-active {
  color: var(--primary,#0284C7);
  background: color-mix(in srgb,var(--primary,#0284C7) 8%,transparent);
  border-bottom-color: var(--primary,#0284C7);
}

.qc-view-content {
  background: var(--surface,#FFF);
  border: var(--tb-ai-card-border);
  border-radius: var(--tb-ai-card-radius);
  box-shadow: var(--tb-ai-card-shadow);
  overflow: hidden;
}

.qc-embed-state-box {
  height: 460px;
  width: 100%;
}

.qc-embed-state-box tb-dashboard-state {
  display: block;
  width: 100%;
  height: 100%;
}

.qc-dedicated-limits {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 24px;
  background: var(--surface, #FFF);
}

@media (max-width:960px) {
  .qc-flow-section {
    grid-template-columns: 1fr;
  }
  .qc-flow-section__embed {
    height: 360px;
  }
}

/* tb-ai-shared-range */
:has(> .tb-ai-shared-range--title) { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px 12px; }
.tb-ai-shared-range--title { margin-left: auto; }
:has(> .tb-ai-shared-range--embed) { display: flex; flex-direction: column; }
.tb-ai-shared-range--embed { align-self: flex-end; flex: none; margin-bottom: 8px; }
:has(> .tb-ai-shared-range--embed) > tb-dashboard-state { flex: 1 1 auto; min-height: 0; height: auto; }

/* tb-ai-responsive */
@media (max-width: 1279px) {
  .qc-flow-section__embed:has(> tb-dashboard-state[stateid="monitor_de_flujo"]) { height: 970px; min-height: 970px; }
  .qc-embed-state-box:has(> tb-dashboard-state[stateid="gr_ficas_de_par_metros"]) { height: 2890px; min-height: 2890px; }
  .qc-embed-state-box:has(> tb-dashboard-state[stateid="an_lisis_comparativo"]) { height: 970px; min-height: 970px; }
}
@media (max-width: 959px) {
  .qc-embed-state-box:has(> tb-dashboard-state[stateid="mapa"]) { height: 570px; min-height: 570px; }
  .qc-embed-state-box:has(> tb-dashboard-state[stateid="alarmas"]) { height: 570px; min-height: 570px; }
}

