const calcRelativeTime = (ts) => {
  if (!ts) return '—';
  const diff = Math.round((Date.now() - ts) / 60000);
  if (diff < 1) return 'hace un momento';
  if (diff < 60) return 'hace ' + diff + ' min';
  if (diff < 1440) return 'hace ' + Math.round(diff / 60) + ' h';
  return 'hace ' + Math.round(diff / 1440) + ' d';
};

const buildSparkline = (pts, w, h) => {
  if (!pts || pts.length < 2) return '';
  const vals = pts.map((p) => p[1]).filter((v) => v !== null && !isNaN(v));
  if (vals.length < 2) return '';
  const min = Math.min(...vals);
  const max = Math.max(...vals);
  const span = max - min || 1;
  const step = w / (pts.length - 1);
  return pts.map((p, i) => {
    const x = (i * step).toFixed(1);
    const y = (h - ((p[1] - min) / span) * (h - 6) - 3).toFixed(1);
    return x + ',' + y;
  }).join(' ');
};

const calcGaugeAndStatus = (val, min, max) => {
  if (val === null || isNaN(val)) {
    return { tone: 'none', label: 'Sin datos', zone: '—', dash: '0 100' };
  }
  if (min === null && max === null) {
    return { tone: 'ok', label: 'Nominal', zone: 'OK', dash: '50 100' };
  }
  const low = min !== null ? min : val - 1;
  const high = max !== null ? max : val + 1;
  const span = high - low || 1;
  const pct = Math.min(100, Math.max(0, ((val - (low - span * 0.2)) / (span * 1.4)) * 100));
  const dash = pct.toFixed(1) + ' 100';

  if (min !== null && val < min) {
    return { tone: 'warn', label: 'Inferior', zone: 'BAJO', dash };
  }
  if (max !== null && val > max) {
    return { tone: 'crit', label: 'Superior', zone: 'ALTO', dash };
  }
  return { tone: 'ok', label: 'Normal', zone: 'NORMAL', dash };
};

