  if (!this.entity || this.busy) return;
  const attrs = [];
  this.params.forEach((p) => {
    if (p.inputMin !== null && p.inputMin !== '') {
      attrs.push({ key: p.minKey, value: Number(p.inputMin) });
    }
    if (p.inputMax !== null && p.inputMax !== '') {
      attrs.push({ key: p.maxKey, value: Number(p.inputMax) });
    }
  });
  if (!attrs.length) return;
  this.busy = true;
  this.saveMessage = '';
  ctx.detectChanges();

  ctx.attributeService.saveEntityAttributes(
    { id: this.entity.id, entityType: this.entity.entityType },
    'SERVER_SCOPE',
    attrs
  ).subscribe({
    next: () => {
      this.params.forEach((p) => {
