    const res = calcGaugeAndStatus(p.value, p.min, p.max);
    p.statusTone = res.tone;
    p.statusLabel = res.label;
    p.zoneShort = res.zone;
    p.gaugeDash = res.dash;
    if (res.tone === 'warn' || res.tone === 'crit') bad++;
  });
  this.outOfRangeCount = bad;
