        } else {
          const target = this.params.find((p) => p.key === k);
          if (target) {
            target.sparklinePts = buildSparkline(series, 120, 32);
            if (series.length >= 2) {
              const first = series[0][1];
              const last = series[series.length - 1][1];
              const diff = last - first;
              target.trendDiff = diff;
              target.trendText = (diff >= 0 ? '+' : '') + diff.toFixed(target.step < 1 ? 2 : 1) + ' vs 1h';
            }
          }
        }
      }
      ctx.detectChanges();
    }
  }
}, true).subscribe((sub) => { tsSubId = sub.id; });

const timeTicker = setInterval(() => {
  if (lastTs) {
    this.lastRelativeStr = calcRelativeTime(lastTs);
    ctx.detectChanges();
  }
}, 60000);

ctx.registerDestroyCallback(() => {
  clearInterval(timeTicker);
  if (latestSubId) ctx.subscriptionApi.removeSubscription(latestSubId);
  if (tsSubId) ctx.subscriptionApi.removeSubscription(tsSubId);
});

